                title: "القشرة (The Crust)",
                text: "هي الطبقة الخارجية الرقيقة التي نعيش عليها. تتكون من الصخور والمعادن، ويختلف سمكها بين القشرة المحيطية والقشرية."
            },
            mantle: {
                title: "الوشاح (The Mantle)",
                text: "طبقة سميكة تحت القشرة تتكون من الصخور الساخنة جداً التي تتحرك ببطء شديد. تمثل معظم حجم الأرض."
            },
            'outer-core': {
                title: "اللب الخارجي (The Outer Core)",
                text: "طبقة سائلة من الحديد والنيكل. حركتها تولد المجال المغناطيسي للأرض."
            },
            'inner-core': {
                title: "اللب الداخلي (The Inner Core)",
                text: "كرة صلبة تتكون من الحديد والنيكل. رغم حرارتها العالية، إلا أنها صلبة بسبب الضغط الهائل."
            }
        };

        function showInfo(layer) {
            const info = data[layer];
            document.getElementById('text').innerHTML = "<strong>" + info.title + ":</strong><br>" + info.text;
        }
    </script>
</body>
</html>
