from collections import defaultdict
from datetime import datetime

def analyze_carrier_otd(input_file, output_file):
    carrier_data = defaultdict(lambda: {
        'TotalDelivered': 0,
        'OnTimeDelivered': 0
    })

    with open(input_file, mode='r', encoding='utf-8') as f:
        reader = csv.DictReader(f)
        for row in reader:
            # Clean all values of trailing whitespace/carriage returns
            row = {k: v.strip() for k, v in row.items()}

            # Filter for successfully delivered orders
            status = row.get('fulfillment_status', '')
            if status != 'Delivered':
                continue

            carrier = row.get('carrier_name') or "Unknown"

            # Parse dates
            actual_date_str = row.get('actual_delivery_date', '')
            estimated_date_str = row.get('estimated_delivery_date', '')

            if not actual_date_str or not estimated_date_str:
                continue

            try:
                # Try the format seen in the data
